const $=s=>document.querySelector(s), menu=$('#menu'), search=$('#search'), scrim=$('#scrim'), query=$('#query');
const names=['Women’s Day Sale','Start Here','For Moms','For Baby','Shop','Explore'];let active='',mode='questions',lastFocus=null;
const img=n=>'assets/'+n;const products=[['S9 Pro Wearable Breast Pump Upgraded','product_img202602041113316.png'],['Wearable Breast Pump','product_imgImage2603554.png'],['Bottle Washer','product_imgImage2603549.png'],['Portable Breast Pump','product_imgImage2603550.png'],['Portable Milk Cooler','product_imgImage2603551.png'],['Wearable Breast Pump','product_imgImage2603552.png'],['Breast Pump Accessory','product_imgImage2603553.png'],['S9 Pro Wearable Breast Pump','product_img202602041113316.png']];
const questions=['What’s the best pump for working moms?','Why is my milk supply dropping?','Why does my baby wake every hour?','How do I choose the right breast pump?'];
const escapeHTML=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const card=(name,asset)=>`<button class="product-card" data-product="${escapeHTML(name)}"><img src="${img(asset)}" alt="${escapeHTML(name)}"><p>${escapeHTML(name)}</p></button>`;
$('nav').innerHTML=names.map(n=>`<button data-nav="${n}" aria-expanded="false">${n}</button>`).join('');
function closePanels(restore=false){menu.classList.remove('campaign-menu');menu.hidden=true;search.hidden=true;scrim.hidden=true;active='';search.classList.remove('fullscreen');document.querySelectorAll('[data-nav]').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-expanded','false')});$('#open-search').setAttribute('aria-expanded','false');if(restore&&lastFocus)lastFocus.focus()}
function showMenu(name){if(active===name){closePanels();return}closePanels();active=name;scrim.hidden=false;menu.hidden=false;const b=[...document.querySelectorAll('[data-nav]')].find(b=>b.dataset.nav===name);b.classList.add('active');b.setAttribute('aria-expanded','true');if(name==='Women’s Day Sale')renderCampaign();else if(name==='Start Here')renderStart();else if(name==='Explore')renderExplore();else renderCatalog(name)}
function renderStart(){const recommendations=['Breast Pumps','Feeding Gear','Bras','Cozy Pregnancy'];const scene=['Pregnancy','Breastfeeding','Postpartum Recovery','On the Go'];const assets=['start_imgImage2603541.png','start_imgImage2603542.png','start_imgImage2603545.png','start_imgImage2603543.png'];menu.innerHTML=`<div class="menu-start"><div><h2>Recommended</h2><div class="start-grid">${recommendations.map((n,i)=>`<button class="start-card" data-next="${n}"><div class="collage"><img src="assets/recommended-official-${i}.webp" alt="${n}"></div><p>${n}</p></button>`).join('')}</div><div class="solutions"><h2>Our Solutions</h2><div class="start-grid">${scene.map((n,i)=>`<button class="start-card" data-next="${n}"><img src="${img(assets[i])}" alt="${n}"><p>${n}</p></button>`).join('')}</div></div></div><div><h2>Baby Registry</h2><a class="registry" style="display:block" href="https://momcozy.com/pages/baby-registry" target="_blank" rel="noopener"><img src="${img('start_imgImage2603547.png')}" alt="Baby registry"><strong>Stay prepared<br>Gain support<br>Start Your Registry Today!</strong></a></div></div>`}
const tabs={ 'For Moms':['Pregnancy','Postpartum','Breastfeeding','On the Go'],'For Baby':['Daily Care','Activity','Safety','Sleep','Shower'],'Shop':['Best Selling','New In','Bundles','Sales','Gift'],'Women’s Day Sale':['Special Offers','Best Sellers','Bundles']};
function renderCatalog(name,tab=0,category=0){const moms=name==='For Moms';const cats=moms?(tab===0?['Maternity Belly Band','Maternity Pillows','Nursing Bras']:tab===2?['Wearable Breast Pumps','Pumping Bras','Breast Care','Accessories']:['Recovery Essentials','Comfort & Care','On-the-Go Essentials']):name==='For Baby'?['Baby Nasal & Thermometer','Oral Care']:['Shop All','Breast Pumps','Feeding','Maternity & Baby'];const ps=moms?(officialCatalog[tab===0?(category===1?'pillow':category===0?'belly':'bras'):tab===2?(category===0?'pump':category===1?'bras':'care'):tab===3?'travel':'care']||[]):name==='For Baby'?Array.from({length:6},(_,i)=>[['Baby Care Kit','Baby Thermometer','Baby Nasal Aspirator','Oral Care Kit','Baby Care Essentials','Nasal Care'][i],`baby_imgImage260356${i+3}.png`]):products;menu.innerHTML=`<div class="pills">${tabs[name].map((n,i)=>`<button data-tab="${i}" class="${i===tab?'selected':''}">${n}</button>`).join('')}</div><div class="catalog"><div class="categories">${cats.map((n,i)=>`<button data-category="${i}" class="${i===category?'selected':''}">${n}</button>`).join('')}</div><div><div class="product-grid">${ps.map(p=>card(...p)).join('')}</div><div class="guides"><h3>Don’t know how to choose?</h3><div class="guide-row"><button data-quiz>Which Pump Fits You? <span>Take a quiz →</span></button><button data-ai>Have more questions to ask? <span>✧ Ask AI Assistant</span></button></div></div></div></div>`;menu.dataset.tab=tab;menu.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>renderCatalog(name,+b.dataset.tab));menu.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>renderCatalog(name,tab,+b.dataset.category))}
function renderExplore(){const ns=['Our Story','Brand Events','Momcozy Care Program','Baby Registry','Community','Podcast'],links=['https://momcozy.com/pages/our-story','https://momcozy.com/pages/momcozy-events','https://momcozy.com/pages/momcozy-care-program','https://momcozy.com/pages/baby-registry','https://community.momcozy.com','https://momcozy.com/pages/momcozy-village-together-we-grow'];menu.innerHTML=`<div class="explore-grid">${ns.map((n,i)=>`<a class="explore-card" href="${links[i]}" target="_blank" rel="noopener"><img src="assets/explore-${i}.png" alt=""><strong>${n}</strong></a>`).join('')}</div>`}
function setMode(m){mode=m;search.classList.toggle('products',m==='products');$('.recommendations').hidden=m!=='products';$('#answer').hidden=true;$('.search-inner').hidden=false;$('.questions').hidden=false}
function openSearch(){lastFocus=document.activeElement;closePanels();search.hidden=false;scrim.hidden=false;$('#open-search').setAttribute('aria-expanded','true');query.value='';updateQuery();setMode('questions');query.focus({preventScroll:true})}
function updateQuery(){$('#clear-query').hidden=!query.value;$('#submit-query').hidden=!query.value;$('#microphone').hidden=!!query.value;$('#show-results span').textContent=query.value||'Bottle Washer'}
function preview(button){const d=$('#preview');d.querySelector('img').src=button.querySelector('img').src;d.querySelector('img').alt=button.dataset.product;d.querySelector('h2').textContent=button.dataset.product;d.showModal()}
function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').hidden=true,3500)}
function submit(){if(!query.value.trim())return;setMode('products');updateQuery()}
$('.chips').innerHTML=['Bottle Washer','Breast Pumps','Pumping Bras','Maternity Pillow','Baby Care','Milk Storage','Travel Essentials','Newborn Gifts'].map(n=>`<button>${n}</button>`).join('');$('.questions').innerHTML=questions.map(n=>`<button>${n} ↗</button>`).join('');$('.search-products').innerHTML=products.map(p=>card(...p)).join('');
document.addEventListener('click',e=>{const nav=e.target.closest('[data-nav]');if(nav){showMenu(nav.dataset.nav);return}const p=e.target.closest('[data-product]');if(p){preview(p);return}if(e.target.closest('[data-ai]'))openSearch();if(e.target.closest('[data-quiz]')){openSearch();query.value='Which breast pump fits my routine?';updateQuery()}const next=e.target.closest('[data-next]');if(next){showMenu('For Moms');return}});
$('#open-search').onclick=openSearch;$('#floating-ai').onclick=openSearch;$('[data-explore]').onclick=()=>showMenu('Explore');$('.logo').onclick=e=>{e.preventDefault();closePanels()};scrim.onclick=()=>closePanels(true);$('#close-search').onclick=()=>closePanels(true);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#preview').open)closePanels(true)});$('#search-form').onsubmit=e=>{e.preventDefault();submit()};query.oninput=()=>{updateQuery();if(query.value.trim())setMode('products');else setMode('questions')};$('#clear-query').onclick=()=>{query.value='';setMode('questions');updateQuery();query.focus()};$('.chips').onclick=e=>{if(e.target.tagName==='BUTTON'){query.value=e.target.textContent;setMode('products');updateQuery();query.focus()}};$('.questions').onclick=e=>{if(e.target.tagName==='BUTTON'){query.value=e.target.textContent.replace(' ↗','');updateQuery();setMode('products')}};function expand(){search.classList.toggle('fullscreen');$('#expand').setAttribute('aria-label',search.classList.contains('fullscreen')?'Collapse search':'Expand search');$('#extend').textContent=search.classList.contains('fullscreen')?'collapse⌃':'extend to full screen⌄'}$('#expand').onclick=expand;$('#extend').onclick=expand;$('#microphone').onclick=()=>toast('Voice input will be available in the connected search experience.');$('#show-results').onclick=()=>{toast(`Showing preview recommendations for “${query.value||'Bottle Washer'}”`)};$('#ask-ai').onclick=()=>{$('.recommendations').hidden=true;$('#answer').hidden=false;$('#answer h2').textContent=query.value||'How can I help you choose?'};$('#back-search').onclick=()=>setMode('questions');$('.dialog-close').onclick=()=>$('#preview').close();$('.preview-back').onclick=()=>$('#preview').close();$('#preview').onclick=e=>{if(e.target===$('#preview'))$('#preview').close()};$('#language').onclick=()=>toast('English · Desktop design preview');

// Shared search controls: 20px icons, 1.75px strokes, 32px hit areas.
const controlIcon = paths => `<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths}</svg>`;
const closeIcon=controlIcon('<path d="m6 6 12 12M18 6 6 18"/>');
$('#clear-query').innerHTML=closeIcon;
$('#close-search').innerHTML=closeIcon;
$('#submit-query').innerHTML=controlIcon('<path d="M4 12h16m-6-6 6 6-6 6"/>');
$('#expand').innerHTML=controlIcon('<path d="M14 4h6v6M20 4l-7 7M10 20H4v-6M4 20l7-7"/>');

function renderCampaign(){
 menu.classList.add('campaign-menu');
 menu.innerHTML='<div class="campaign-dropdown"><button class="campaign-card" aria-label="Explore Momcozy Brand Day"><img src="assets/campaign-brand-day.png" alt="Momcozy Brand Day — Mom, and More. Motherhood Expands You"></button><button class="campaign-card" aria-label="Explore Cozy by You"><img src="assets/campaign-cozy-by-you.png" alt="Cozy by You — From Real Voices to Real Change, Led by Moms"></button></div>';
 menu.querySelectorAll('.campaign-card').forEach(card=>card.onclick=()=>showMenu('Shop'));
}

// Preserve line breaks and an uninterrupted accessible heading while words reveal.
const greetingHeading=$('.greeting h1');
const greetingLines=greetingHeading.innerHTML.split(/<br\s*\/?\s*>/i);
greetingHeading.setAttribute('aria-label',greetingHeading.textContent);
let greetingWordIndex=0;
greetingHeading.innerHTML=greetingLines.map(line=>line.split(/(\s+)/).map(word=>word.trim()?`<span class="greeting-word" aria-hidden="true" style="--word-delay:${120+greetingWordIndex++*65}ms">${escapeHTML(word)}</span>`:word).join('')).join('<br>');
